package com.neelastack.lakhdatar.repository;
import com.neelastack.lakhdatar.domain.User; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Lock; import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.Query; import java.util.Optional; import java.util.UUID;
public interface UserRepository extends JpaRepository<User,Long>{ Optional<User> findByEmailIgnoreCase(String email); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select u from User u where u.id = :id") Optional<User> findByIdForUpdate(Long id); boolean existsByRole(com.neelastack.lakhdatar.domain.Enums.UserRole role); Optional<User> findByPublicId(UUID publicId); }
